-- =============================================================================================
-- Hand-written below this line: vendor and document checks, names unique among live vendors,
-- archiving final and only without open work, documents corrected only by voiding; work orders
-- may go to an active vendor (assigned work has a technician, a vendor or both), each vendor
-- change logged by the database. See docs/architecture/DATA_MODEL.md section 9 (Vendors).
-- =============================================================================================

ALTER TABLE "vendors" ADD CONSTRAINT "vendors_text"
  CHECK ("name" = btrim("name") AND length("name") BETWEEN 1 AND 160
         AND ("contact_name" IS NULL OR ("contact_name" = btrim("contact_name") AND length("contact_name") BETWEEN 1 AND 160))
         AND ("email" IS NULL OR ("email" = lower(btrim("email")) AND "email" ~ '^[^@[:space:]]+@[^@[:space:]]+\.[^@[:space:]]+$' AND length("email") <= 254))
         AND ("phone" IS NULL OR ("phone" = btrim("phone") AND length("phone") BETWEEN 3 AND 40))
         AND ("tax_reference" IS NULL OR ("tax_reference" = btrim("tax_reference") AND length("tax_reference") BETWEEN 1 AND 60))
         AND ("notes" IS NULL OR ("notes" = btrim("notes") AND length("notes") BETWEEN 1 AND 2000))
         AND ("status_note" IS NULL OR ("status_note" = btrim("status_note") AND length("status_note") BETWEEN 1 AND 1000)));
ALTER TABLE "vendors" ADD CONSTRAINT "vendors_status"
  CHECK (("status" = 'ARCHIVED') = ("archived_at" IS NOT NULL)
         AND ("status" = 'SUSPENDED') = ("status_note" IS NOT NULL));
CREATE UNIQUE INDEX "vendors_live_name_key" ON "vendors" ("organisation_id", lower("name"))
  WHERE "status" <> 'ARCHIVED';

CREATE FUNCTION app_vendor_guard() RETURNS trigger
  LANGUAGE plpgsql
  AS $$
BEGIN
  IF TG_OP = 'INSERT' THEN
    IF NEW."status" <> 'ACTIVE' THEN
      RAISE EXCEPTION 'vendors start active' USING ERRCODE = 'check_violation';
    END IF;
    NEW."created_at" := now();
    NEW."archived_at" := NULL;
    RETURN NEW;
  END IF;
  IF OLD."status" = 'ARCHIVED' THEN
    RAISE EXCEPTION 'vendor % is archived and no longer changes', OLD."id" USING ERRCODE = 'check_violation';
  END IF;
  IF (NEW."organisation_id", NEW."created_at") IS DISTINCT FROM (OLD."organisation_id", OLD."created_at") THEN
    RAISE EXCEPTION 'vendor % cannot move to another organisation', OLD."id" USING ERRCODE = 'check_violation';
  END IF;
  NEW."archived_at" := OLD."archived_at";
  IF NEW."status" = 'ARCHIVED' THEN
    IF EXISTS (SELECT 1 FROM "work_orders" WHERE "vendor_id" = OLD."id"
                  AND "status" NOT IN ('COMPLETED', 'CANCELLED')) THEN
      RAISE EXCEPTION 'reassign or finish the open work of this vendor before archiving it'
        USING ERRCODE = 'check_violation';
    END IF;
    NEW."archived_at" := now();
    NEW."status_note" := NULL;
  ELSIF NEW."status" = 'ACTIVE' THEN
    NEW."status_note" := NULL;
  END IF;
  RETURN NEW;
END
$$;

CREATE TRIGGER "vendors_guard"
  BEFORE INSERT OR UPDATE ON "vendors"
  FOR EACH ROW EXECUTE FUNCTION app_vendor_guard();

ALTER TABLE "vendor_documents" ADD CONSTRAINT "vendor_documents_text"
  CHECK ("title" = btrim("title") AND length("title") BETWEEN 1 AND 160
         AND ("reference" IS NULL OR ("reference" = btrim("reference") AND length("reference") BETWEEN 1 AND 120))
         AND ("void_reason" IS NULL OR ("void_reason" = btrim("void_reason") AND length("void_reason") BETWEEN 1 AND 500)));
ALTER TABLE "vendor_documents" ADD CONSTRAINT "vendor_documents_dates"
  CHECK ("valid_from" IS NULL OR "expires_on" IS NULL OR "expires_on" >= "valid_from");
ALTER TABLE "vendor_documents" ADD CONSTRAINT "vendor_documents_void"
  CHECK (("voided_at" IS NULL) = ("void_reason" IS NULL)
         AND ("voided_at" IS NULL) = ("voided_by_user_id" IS NULL));

CREATE FUNCTION app_vendor_document_guard() RETURNS trigger
  LANGUAGE plpgsql
  AS $$
BEGIN
  IF TG_OP = 'INSERT' THEN
    IF NEW."voided_at" IS NOT NULL THEN
      RAISE EXCEPTION 'a document is added unvoided' USING ERRCODE = 'check_violation';
    END IF;
    IF EXISTS (SELECT 1 FROM "vendors" WHERE "id" = NEW."vendor_id" AND "status" = 'ARCHIVED') THEN
      RAISE EXCEPTION 'the vendor is archived' USING ERRCODE = 'check_violation';
    END IF;
    NEW."created_at" := now();
    RETURN NEW;
  END IF;
  IF OLD."voided_at" IS NOT NULL OR NEW."voided_at" IS NULL
     OR (NEW."organisation_id", NEW."vendor_id", NEW."kind", NEW."title", NEW."reference", NEW."valid_from",
         NEW."expires_on", NEW."created_by_user_id", NEW."created_at")
        IS DISTINCT FROM
        (OLD."organisation_id", OLD."vendor_id", OLD."kind", OLD."title", OLD."reference", OLD."valid_from",
         OLD."expires_on", OLD."created_by_user_id", OLD."created_at") THEN
    RAISE EXCEPTION 'document % is never edited; void it once and add it again', OLD."id"
      USING ERRCODE = 'check_violation';
  END IF;
  NEW."voided_at" := now();
  RETURN NEW;
END
$$;

CREATE TRIGGER "vendor_documents_guard"
  BEFORE INSERT OR UPDATE ON "vendor_documents"
  FOR EACH ROW EXECUTE FUNCTION app_vendor_document_guard();

-- Assigned, started, paused and completed work has a technician, a vendor or both.
ALTER TABLE "work_orders" DROP CONSTRAINT "work_orders_assignee";
ALTER TABLE "work_orders" ADD CONSTRAINT "work_orders_assignee"
  CHECK (CASE "status"
           WHEN 'OPEN' THEN "assigned_to_user_id" IS NULL AND "vendor_id" IS NULL
           WHEN 'CANCELLED' THEN true
           ELSE "assigned_to_user_id" IS NOT NULL OR "vendor_id" IS NOT NULL
         END);

-- Work goes only to an active vendor.
CREATE FUNCTION app_work_order_vendor_check() RETURNS trigger
  LANGUAGE plpgsql
  AS $$
BEGIN
  IF NEW."vendor_id" IS NOT NULL
     AND (TG_OP = 'INSERT' OR NEW."vendor_id" IS DISTINCT FROM OLD."vendor_id")
     AND NOT EXISTS (SELECT 1 FROM "vendors" WHERE "id" = NEW."vendor_id" AND "status" = 'ACTIVE') THEN
    RAISE EXCEPTION 'work goes only to an active vendor' USING ERRCODE = 'check_violation';
  END IF;
  RETURN NEW;
END
$$;

CREATE TRIGGER "work_orders_vendor_check"
  BEFORE INSERT OR UPDATE ON "work_orders"
  FOR EACH ROW EXECUTE FUNCTION app_work_order_vendor_check();

CREATE OR REPLACE FUNCTION app_work_order_guard() RETURNS trigger
  LANGUAGE plpgsql
  AS $$
DECLARE
  transition text := OLD."status" || '>' || NEW."status";
  needs_note boolean;
BEGIN
  IF OLD."status" IN ('COMPLETED', 'CANCELLED') THEN
    RAISE EXCEPTION 'work order % is % and no longer changes', OLD."id", lower(OLD."status"::text)
      USING ERRCODE = 'check_violation';
  END IF;
  IF (NEW."organisation_id", NEW."property_id", NEW."request_id", NEW."unit_id", NEW."common_area_id",
      NEW."work_order_number", NEW."created_by_user_id", NEW."created_at")
     IS DISTINCT FROM
     (OLD."organisation_id", OLD."property_id", OLD."request_id", OLD."unit_id", OLD."common_area_id",
      OLD."work_order_number", OLD."created_by_user_id", OLD."created_at") THEN
    RAISE EXCEPTION 'work order % cannot move to another request, place or number', OLD."id"
      USING ERRCODE = 'check_violation';
  END IF;
  IF OLD."request_id" IS NOT NULL THEN
    PERFORM pg_advisory_xact_lock(hashtextextended('veyra.maintenance_request:' || OLD."request_id"::text, 0));
  END IF;
  NEW."started_at" := OLD."started_at";
  NEW."completed_at" := OLD."completed_at";

  IF NEW."status" = OLD."status" THEN
    NEW."status_note" := OLD."status_note";
    IF (NEW."assigned_to_user_id", NEW."vendor_id") IS DISTINCT FROM (OLD."assigned_to_user_id", OLD."vendor_id")
       AND NEW."status" = 'OPEN' THEN
      RAISE EXCEPTION 'assigning work moves it to assigned' USING ERRCODE = 'check_violation';
    END IF;
    RETURN NEW;
  END IF;
  IF transition NOT IN ('OPEN>ASSIGNED', 'OPEN>CANCELLED',
                        'ASSIGNED>OPEN', 'ASSIGNED>IN_PROGRESS', 'ASSIGNED>CANCELLED',
                        'IN_PROGRESS>ON_HOLD', 'IN_PROGRESS>COMPLETED', 'IN_PROGRESS>CANCELLED',
                        'ON_HOLD>IN_PROGRESS', 'ON_HOLD>CANCELLED') THEN
    RAISE EXCEPTION 'a work order cannot go from % to %', lower(OLD."status"::text), lower(NEW."status"::text)
      USING ERRCODE = 'check_violation';
  END IF;
  needs_note := NEW."status" IN ('ON_HOLD', 'COMPLETED', 'CANCELLED');
  IF needs_note AND NEW."status_note" IS NULL THEN
    RAISE EXCEPTION 'say why the work is %',
      CASE NEW."status" WHEN 'ON_HOLD' THEN 'on hold' WHEN 'COMPLETED' THEN 'complete (what was done)' ELSE 'cancelled' END
      USING ERRCODE = 'check_violation';
  END IF;
  IF NOT needs_note THEN
    NEW."status_note" := NULL;
  END IF;
  IF NEW."status" = 'IN_PROGRESS' AND OLD."started_at" IS NULL THEN
    NEW."started_at" := now();
  ELSIF NEW."status" = 'COMPLETED' THEN
    NEW."completed_at" := now();
  END IF;
  RETURN NEW;
END
$$;

CREATE OR REPLACE FUNCTION app_work_order_log() RETURNS trigger
  LANGUAGE plpgsql
  AS $$
BEGIN
  IF TG_OP = 'INSERT' THEN
    PERFORM app_maintenance_log(NEW."organisation_id", NEW."property_id", NEW."request_id", NEW."id", 'STATUS_CHANGED',
                                'INTERNAL', NULL, NEW."status"::text, NULL);
    IF NEW."assigned_to_user_id" IS NOT NULL THEN
      PERFORM app_maintenance_log(NEW."organisation_id", NEW."property_id", NEW."request_id", NEW."id", 'ASSIGNEE_CHANGED',
                                  'INTERNAL', NULL, NEW."assigned_to_user_id"::text, NULL);
    END IF;
    IF NEW."vendor_id" IS NOT NULL THEN
      PERFORM app_maintenance_log(NEW."organisation_id", NEW."property_id", NEW."request_id", NEW."id", 'VENDOR_CHANGED',
                                  'INTERNAL', NULL, NEW."vendor_id"::text, NULL);
    END IF;
    RETURN NULL;
  END IF;
  IF NEW."status" IS DISTINCT FROM OLD."status" THEN
    PERFORM app_maintenance_log(NEW."organisation_id", NEW."property_id", NEW."request_id", NEW."id", 'STATUS_CHANGED',
                                'INTERNAL', OLD."status"::text, NEW."status"::text, NEW."status_note");
  END IF;
  IF NEW."assigned_to_user_id" IS DISTINCT FROM OLD."assigned_to_user_id" THEN
    PERFORM app_maintenance_log(NEW."organisation_id", NEW."property_id", NEW."request_id", NEW."id", 'ASSIGNEE_CHANGED',
                                'INTERNAL', OLD."assigned_to_user_id"::text, NEW."assigned_to_user_id"::text, NULL);
  END IF;
  IF NEW."vendor_id" IS DISTINCT FROM OLD."vendor_id" THEN
    PERFORM app_maintenance_log(NEW."organisation_id", NEW."property_id", NEW."request_id", NEW."id", 'VENDOR_CHANGED',
                                'INTERNAL', OLD."vendor_id"::text, NEW."vendor_id"::text, NULL);
  END IF;
  IF NEW."priority" IS DISTINCT FROM OLD."priority" THEN
    PERFORM app_maintenance_log(NEW."organisation_id", NEW."property_id", NEW."request_id", NEW."id", 'PRIORITY_CHANGED',
                                'INTERNAL', OLD."priority"::text, NEW."priority"::text, NULL);
  END IF;
  RETURN NULL;
END
$$;

DO $$
DECLARE
  t text;
BEGIN
  FOREACH t IN ARRAY ARRAY['vendors', 'vendor_documents'] LOOP
    EXECUTE format('ALTER TABLE %I ENABLE ROW LEVEL SECURITY', t);
    EXECUTE format('ALTER TABLE %I FORCE ROW LEVEL SECURITY', t);
    EXECUTE format('CREATE POLICY %I ON %I FOR SELECT USING (organisation_id = app_current_organisation_id())', t || '_select', t);
    EXECUTE format('CREATE POLICY %I ON %I FOR INSERT WITH CHECK (organisation_id = app_current_organisation_id())', t || '_insert', t);
    EXECUTE format('CREATE POLICY %I ON %I FOR UPDATE USING (organisation_id = app_current_organisation_id()) WITH CHECK (organisation_id = app_current_organisation_id())', t || '_update', t);
  END LOOP;
END
$$;

REVOKE ALL ON "vendors", "vendor_documents" FROM PUBLIC;
GRANT SELECT, INSERT, UPDATE ON "vendors", "vendor_documents" TO veyra_app;
